INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('겐로쿠엔', '兼六園', 'PARK_GARDEN', '石川県', '金沢市', 36.562600, 136.662600, 'FIXED', '08:00', '17:00', NULL, '3/1~10/15는 7:00~18:00, 10/16~2월 말은 8:00~17:00. 마지막 입장 30분 전. 연말연시(12/31~1/3) 무료 개원', '320엔', '미토 가이라쿠엔·오카야마 고라쿠엔과 함께 일본 3대 정원으로 꼽히는 가가 번주 마에다 가문의 회유식 정원.', '11월 1일부터 소나무에 눈 무게를 막는 유키즈리 작업을 해, 겨울 풍경이 겐로쿠엔의 상징이다.', NULL, 'http://www.pref.ishikawa.jp/siro-niwa/kenrokuen/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히가시 차야 거리', 'ひがし茶屋街', 'HISTORIC', '石川県', '金沢市', 36.572500, 136.666400, 'ALWAYS', NULL, NULL, NULL, '거리는 상시. 가게마다 영업시간이 다름', '무료', '에도 시대 찻집 건물이 늘어선 가나자와의 옛 거리.', '가게는 대개 저녁에 닫아서 낮 시간에 걷는 게 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('다카야마 진야', '高山陣屋', 'HISTORIC', '岐阜県', '高山市', 36.139300, 137.257800, 'FIXED', '08:45', '16:30', NULL, '4~10월은 17:00까지. 마지막 입장 30분 전. 연말연시(12/29~1/3) 휴관', '500엔 (고등학생 이하 무료)', '에도 시대에 막부가 히다를 직접 다스리던 관청. 주요 건물이 남아 있는 곳은 전국에서 여기뿐이다.', '정문 앞 광장에서 아침마다 진야마에 아침 시장이 열린다.', NULL, 'https://jinya.gifu.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히다노사토', '飛騨の里', 'MUSEUM', '岐阜県', '高山市', 36.135700, 137.240000, 'FIXED', '08:30', '17:00', NULL, '무휴. 라이트업 기간에는 야간 연장', '700엔', '갓쇼즈쿠리 등 히다 지방의 옛 민가 30여 채를 옮겨 복원한 야외 박물관. 국가 중요문화재 4채가 포함돼 있다.', '짚 공예·사시코 실연이 날마다 바뀌어 열린다. 넉넉히 2~3시간 잡자.', NULL, 'https://hidanosato.com/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('군조하치만성', '郡上八幡城', 'HISTORIC', '岐阜県', '郡上市', 35.751000, 136.961700, 'FIXED', '09:00', '17:00', NULL, '6~8월 8:00~18:00, 11~2월 9:00~16:30. 마지막 입장 15분 전. 12/20~1/10 휴관, 라이트업 기간 연장', '400엔', '1933년에 목조로 다시 지은 천수각으로, 현존하는 목조 재건 성 가운데 일본에서 가장 오래됐다. 꼭대기에서 성 아래 마을이 내려다보인다.', '11월 초~중순 단풍 철에는 야간 라이트업을 한다.', NULL, 'https://hachiman-castle.com/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('소기스이', '宗祇水', 'HISTORIC', '岐阜県', '郡上市', 35.748600, 136.963500, 'ALWAYS', NULL, NULL, NULL, '상시', '무료', '"명수 100선"에 뽑힌 군조하치만 성 아래 마을의 샘물.', '수로가 이어진 "물의 마을" 골목 산책과 묶어 돌기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나고야성', '名古屋城', 'HISTORIC', '愛知県', '名古屋市中区', 35.185300, 136.899000, 'FIXED', '09:00', '16:30', NULL, '폐문 17:00. 혼마루 어전 입장 16:00까지. 천수각은 현재 입장 불가. 12/29~1/1 휴관, 축제 기간엔 연장', '1,000엔 (2026년 10월부터, 중학생 이하 무료)', '도쿠가와 가문의 성. 화려한 장벽화로 꾸민 혼마루 어전을 둘러볼 수 있다.', '봄 벚꽃 축제 기간에는 밤 19:30까지 연다.', NULL, 'https://www.nagoyajo.city.nagoya.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('아쓰타 신궁', '熱田神宮', 'SHRINE_TEMPLE', '愛知県', '名古屋市熱田区', 35.127900, 136.908600, 'ALWAYS', NULL, NULL, NULL, '경내 상시. 보물관 9:00~16:30 (매월 마지막 수·목요일, 12/25~1/3 휴관)', '무료', '나고야를 대표하는 신사. 경내는 언제든 참배할 수 있다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히가시야마 동식물원', '東山動植物園', 'AMUSEMENT', '愛知県', '名古屋市千種区', 35.156500, 136.977600, 'FIXED', '09:00', '16:50', 'MON', '입장 16:30까지. 월요일이 공휴일이면 다음 평일 휴원. 12/29~1/1 휴원', '800엔 (2026년 10월부터, 중학생 이하 무료)', '동물원·식물원·유원지·스카이타워가 한곳에 모인 약 60ha 공원. 식물원 대온실 앞관은 현존하는 온실 중 일본에서 가장 오래됐다.', '스카이타워(9:00~21:30)는 동식물원보다 늦게까지 열어 야경을 볼 수 있다.', NULL, 'https://www.higashiyama.city.nagoya.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('국영 에치고 구릉공원', '国営越後丘陵公園', 'PARK_GARDEN', '新潟県', '長岡市', 37.374400, 138.794000, 'FIXED', '09:30', '16:30', NULL, '4~10월은 17:00까지. 1~3월 월요일(공휴일이면 다음 날)·12/26~1/1 휴원, 4~12월은 부정기 휴원 (공식 달력 확인)', '450엔 (12~3월 무료, 중학생 이하 무료)', '호쿠리쿠 유일의 국영공원. 놀이 시설이 모인 건강 존과 자연을 걷는 사토야마 필드 뮤지엄으로 나뉜다.', '봄 튤립·장미, 가을 코스모스가 피고 겨울엔 썰매장이 열린다.', NULL, 'http://echigo-park.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가나자와성 공원', '金沢城公園', 'HISTORIC', '石川県', '金沢市', 36.565600, 136.659600, 'FIXED', '08:00', '17:00', NULL, '3/1~10/15는 7:00~18:00, 10/16~2월 말은 8:00~17:00. 무휴. 해 진 뒤~21:00 라이트업. 히시야구라·고짓켄나가야 등 건물 내부는 유료(320엔)', '무료', '가가 번주 마에다 가문이 살던 성터를 정비한 공원. 에도 시대 모습이 남은 이시카와몬·산짓켄나가야와 복원한 건물들이 있다.', '겐로쿠엔 바로 옆이라 이어서 돌기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히다 다카야마 옛 거리', '飛騨高山 古い町並', 'HISTORIC', '岐阜県', '高山市', 36.142600, 137.261300, 'ALWAYS', NULL, NULL, NULL, '거리는 상시. 가게마다 영업시간이 다름', '무료', '에도 시대 상가가 늘어선 다카야마 옛 시가지.', '다카야마 진야와 미야가와 아침시장이 걸어서 닿는 거리다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('미야가와 아침시장', '宮川朝市', 'MARKET', '岐阜県', '高山市', 36.143600, 137.259900, 'FIXED', '07:00', '12:00', NULL, '12~3월은 8:00부터. 연중무휴. 날씨에 따라 가게 수가 줄고, 다 팔리면 일찍 닫는 가게도 있음', '무료', '에도 시대부터 이어진 아침시장. 미야가와 강변 약 350m에 흰 천막 노점이 늘어서 채소·과일·절임·공예품을 판다.', '이른 시간일수록 가게가 많고, 아침에 딴 채소는 일찍 동난다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나가오카 유큐잔 공원', '悠久山公園', 'PARK_GARDEN', '新潟県', '長岡市', 37.438600, 138.880600, 'ALWAYS', NULL, NULL, NULL, '공원은 종일 개방. 소동물원 9:00~17:00', '무료', '"오야마"라 불리는 나가오카 시민의 공원. 벚꽃 약 2,500그루로 "일본 벚꽃 명소 100선"에 뽑혔고 무료 소동물원·향토사료관이 있다.', '벚꽃 철에는 18:00~21:00 밤벚꽃 라이트업을 한다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나가오카시 향토사료관', '長岡市郷土史料館', 'MUSEUM', '新潟県', '長岡市', 37.437200, 138.883800, 'FIXED', '09:00', '17:00', 'MON', '입관 16:30까지. 공휴일 다음 날(토·일 제외)·12/28~1/4 휴관, 벚꽃 축제 기간은 무휴', '300엔', '유큐잔 공원 언덕 위의 성 모양 사료관. 나가오카 출신 선인들의 업적을 소개하고, 4층 전망대에서 시내가 내려다보인다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('야마모토 이소로쿠 기념관', '山本五十六記念館', 'MUSEUM', '新潟県', '長岡市', 37.445800, 138.848700, 'FIXED', '10:00', '17:00', NULL, '12/28~1/4 휴관. 전시 교체로 임시 휴관 있음', '500엔', '나가오카 출신 야마모토 이소로쿠의 생애와 유품을 전시한 기념관.', '나가오카역에서 걸어서 10분.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나고야항 수족관', '名古屋港水族館', 'AMUSEMENT', '愛知県', '名古屋市港区', 35.090900, 136.878600, 'VARIES', NULL, NULL, NULL, '보통 9:30~17:30, 겨울(12월~3월 중순) 17:00까지, GW·여름방학 20:00까지. 월요일 휴관(공휴일이면 다음 날), 7~9월·봄방학·GW·연말연시는 무휴', '2,030엔', '범고래·돌고래가 있는 북관과 일본 바다부터 남극까지를 도는 남관으로 이뤄진 수족관.', '정어리 약 3만 5천 마리가 소용돌이치는 "정어리 토네이도"가 볼거리다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도쿠가와엔', '徳川園', 'PARK_GARDEN', '愛知県', '名古屋市東区', 35.184600, 136.933200, 'FIXED', '09:30', '17:30', 'MON', '입장 17:00까지. 월요일이 공휴일이면 다음 평일 휴원. 12/29~1/1 휴원', '300엔 (중학생 이하 무료)', '약 4.5ha 일본 정원으로, 도쿠가와 미술관과 붙어 있다.', '류몬 폭포는 20분마다 물이 불어 징검돌이 잠기게 꾸며져 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가나자와 21세기 미술관', '金沢21世紀美術館', 'MUSEUM', '石川県', '金沢市', 36.560900, 136.658100, 'FIXED', '10:00', '18:00', 'MON', '전시 존 기준, 금·토는 20:00까지. 무료인 교류 존은 9:00~22:00. 월요일이 공휴일이면 다음 평일 휴관, 연말연시 휴관. 2027/5/6~2028년 3월(예정) 대규모 보수로 휴관', '교류 존 무료, 전시는 전시마다 다름', '"마을에 열린 공원 같은 미술관"을 내건 원형 유리 건물의 현대미술관.', '무료인 교류 존에서도 상설 작품 일부를 볼 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오미초 시장', '近江町市場', 'MARKET', '石川県', '金沢市', 36.571600, 136.656700, 'VARIES', NULL, NULL, NULL, '가게마다 다름 (대체로 9:00~17:00). 휴일도 가게마다 다름', '무료', '가나자와 시내 한가운데 있는 시장.', '가나자와역에서 걸어서 15분, 버스로는 "무사시가쓰지·오미초 시장" 정류장 바로 앞.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('군조하치만 박람관', '郡上八幡博覧館', 'MUSEUM', '岐阜県', '郡上市', 35.749600, 136.961400, 'FIXED', '09:30', '17:00', NULL, '마지막 입장 16:30. 12/24~1/2 휴관', '540엔', '1920년에 지은 옛 세무서 건물을 그대로 쓴 박물관. 군조하치만의 역사·물·기술·군조 오도리를 나눠 소개한다.', '군조 오도리 실연도 볼 수 있다.', NULL, 'https://hakurankan.com/', DATE '2026-11-22', NULL);
INSERT INTO spot_hours (spot_id, start_md, end_md, open_time, close_time, closed_days, is_closed) SELECT id, '03-01', '10-15', '07:00', '18:00', NULL, 0 FROM spots WHERE name_ja = '兼六園';
